    @PublicAPI(usage = ACCESS)
    public FreezingArchRule because(String reason) {
        return new FreezingArchRule(delegate.because(reason), store, matcher);
    }

    @Override
    @PublicAPI(usage = ACCESS)
    public ArchRule allowEmptyShould(boolean allowEmptyShould) {
