        if (!initializationSuccessful) {
            throw new StoreInitializationFailedException(String.format(message, args));
        }
    }

    private void repairStoredRules() {
        Map<String, String> fileNamesByRule = storedRules.asMap();
        Set<String> sharedRules = findSharedRules(fileNamesByRule);
        Set<String> discardedRules = new HashSet<>();
        fileNamesByRule.forEach((rule, fileName) -> {
            if (!sharedRules.contains(rule) && discardIfBrokenOrResolved(rule, fileName)) {
                discardedRules.add(rule);
            }
        });
        storedRules.removeAll(discardedRules);
    }

    private boolean discardIfBrokenOrResolved(String rule, String fileName) {
        Optional<Path> ruleFile = findRuleFile(fileName);
        boolean broken = !ruleFile.isPresent();
        if (!broken && !hasNoViolations(fileName)) {
            return false;
        }
        if (!storeUpdateAllowed) {
            log.warn("Not discarding {} rule '{}' stored in {}, because updating frozen violations is disabled (enable by configuration {}.{}=true)",
                    broken ? "broken" : "resolved", rule, fileName, ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME);
            return false;
        }
        if (broken) {
            log.info("Discarding rule '{}', because {} is no regular file directly within {}", rule, fileName, storeFolder.getAbsolutePath());
            return true;
        }
        try {
            deleteRuleFile(ruleFile.get());
        } catch (IOException e) {
            log.warn("Cannot delete file {} of resolved rule '{}'", fileName, rule, e);
            return false;
        }
        log.info("Discarded resolved rule '{}' together with its file {}", rule, fileName);
        return true;
    }

    private boolean hasNoViolations(String fileName) {
        try {
            return readLines(fileName).isEmpty();
        } catch (StoreReadException e) {
            log.warn("Cannot read rule violation file {}", fileName, e);
            return false;
        }
    }

    /**
     * @return The regular file directly within the store folder the file name of an entry points to, or empty if the entry is broken
     */
    private Optional<Path> findRuleFile(String fileName) {
        try {
            Path relativePath = Paths.get(fileName);
            if (relativePath.getRoot() != null || relativePath.getNameCount() != 1) {
                return Optional.empty();
            }
            Path ruleFile = storeFolder.toPath().resolve(relativePath);
            return Files.isRegularFile(ruleFile) ? Optional.of(ruleFile) : Optional.empty();
        } catch (InvalidPathException e) {
            return Optional.empty();
        }
    }

    private Set<String> findSharedRules(Map<String, String> fileNamesByRule) {
        // rules are shared if they point to the same file name or to the same regular file (no matter if through links)
        SetMultimap<Object, String> rulesByTarget = HashMultimap.create();
        fileNamesByRule.forEach((rule, fileName) -> {
            rulesByTarget.put(normalizedFileName(fileName), rule);
            regularFileKey(fileName).ifPresent(fileKey -> rulesByTarget.put(fileKey, rule));
        });
        return rulesByTarget.asMap().values().stream()
                .filter(rules -> rules.size() > 1)
                .flatMap(Collection::stream)
                .collect(toSet());
    }

    private Object normalizedFileName(String fileName) {
        try {
            return storeFolder.getAbsoluteFile().toPath().resolve(fileName).normalize();
        } catch (InvalidPathException e) {
            return fileName;
        }
    }

    private Optional<Object> regularFileKey(String fileName) {
        try {
            Path file = storeFolder.toPath().resolve(fileName);
            BasicFileAttributes attributes = Files.readAttributes(file, BasicFileAttributes.class);
            if (!attributes.isRegularFile()) {
                return Optional.empty();
            }
            // file keys also identify hard links, but are not supported by every file system
            return Optional.of(attributes.fileKey() != null ? attributes.fileKey() : file.toRealPath());
        } catch (InvalidPathException | IOException e) {
            return Optional.empty();
        }
    }

    private void deleteRuleFile(Path ruleFile) throws IOException {
        if (Files.isSymbolicLink(ruleFile)) {
            Files.delete(ruleFile.toRealPath());
        }
        Files.delete(ruleFile);
    }
